extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var scene_node: Node = await instantiate_scene("res://quiz_audio_controller.tscn")
	if not check("scene_exists", scene_node != null, "La scena quiz_audio_controller.tscn deve istanziarsi correttamente"):
		return

	var controller := scene_node as QuizAudioController
	if not check("is_controller", controller != null, "La radice deve essere di tipo QuizAudioController con script collegato"):
		return

	await wait_frames(3)

	var click_player := find_by_name(controller, "ClickPlayer") as AudioStreamPlayer
	if not check("has_click_player", click_player != null, "Deve essere presente un AudioStreamPlayer chiamato ClickPlayer"):
		return

	check("click_bus_sfx", click_player.bus == &"SFX" or click_player.bus == "SFX", "Il bus di ClickPlayer deve essere 'SFX' (è '%s')" % str(click_player.bus))
	check("click_stream_assigned", click_player.stream != null, "ClickPlayer deve avere uno stream assegnato")

	var feedback_node = get_prop(controller, "feedback")
	check("has_feedback", feedback_node != null, "La proprietà feedback deve riferirsi al nodo QuizAudioFeedback")

	var music_node = get_prop(controller, "music")
	check("has_music", music_node != null, "La proprietà music deve riferirsi al nodo QuizMusicPlayer")

	if controller.has_method("play_click"):
		controller.play_click()
		await wait_frames(2)
		check("click_playing", call_if_exists(controller, "is_click_playing", [], false), "Dopo play_click(), is_click_playing() deve restituire true")
		check("click_volume", absf(click_player.volume_db - get_prop(controller, "click_volume_db", -4.0)) < 0.2, "Il volume di ClickPlayer deve corrispondere a click_volume_db")
		check("click_pitch_range", click_player.pitch_scale >= get_prop(controller, "min_pitch", 0.95) - 0.05 and click_player.pitch_scale <= get_prop(controller, "max_pitch", 1.05) + 0.05, "L'intonazione di ClickPlayer deve rientrare nell'intervallo casuale tra min_pitch e max_pitch (è %.3f)" % click_player.pitch_scale)

	if controller.has_method("play_answer_feedback") and feedback_node != null:
		controller.play_answer_feedback(true)
		await wait_frames(2)
		var fb_playing = call_if_exists(feedback_node, "is_feedback_playing", [], false)
		check("feedback_correct_active", fb_playing, "Chiamando play_answer_feedback(true), il feedback delle risposte deve attivarsi")

	if controller.has_method("start_bg_music") and music_node != null:
		controller.start_bg_music()
		await wait_frames(2)
		var music_playing = call_if_exists(music_node, "is_music_playing", [], false)
		check("music_started", music_playing, "Dopo start_bg_music(), la musica di sottofondo deve essere in riproduzione")

	if controller.has_method("stop_bg_music") and music_node != null:
		controller.stop_bg_music()
		await wait_frames(2)
		var music_stopped := not call_if_exists(music_node, "is_music_playing", [], true)
		check("music_stopped", music_stopped, "Dopo stop_bg_music(), la musica di sottofondo deve fermarsi")
